[p('Patch Compliance','Patch Compliance'),p('Target95% · Actual91%','เป้า 95% · ผลจริง 91%'),p('Needs Improvement','ต้องปรับปรุง')],
[p('MFA Adoption','MFA Adoption'),p('Target100% · Actual97%','เป้า 100% · ผลจริง 97%'),p('Needs Improvement','ต้องปรับปรุง')],
